import {createMotionMedia} from './motion-media.js?v=5.9.0';
import {explorationPresentation} from './origin-cinema.js?v=5.18.0';
import {expansionCinematics,expansionEarned,tacticKeys,STORY_ART} from './expansion-cinema-content.js?v=5.41';
import {drawExpansion} from './expansion-cinema-render.js?v=5.9.0';
import {seenCinematic} from './cinema-content.js?v=5.38';
/** Presentation-only observer. Nothing here awards, consumes, unlocks, moves or advances gameplay. */
export function installExpansionCinema(cinema,{manifest=null}={}){const entries=expansionCinematics();const ids=new Set(entries.map(e=>e.id));cinema.entries=cinema.entries.filter(e=>!ids.has(e.id));cinema.entries.push(...entries);for(const e of entries)cinema.map.set(e.id,e);for(const art of Object.values(STORY_ART))cinema.image(art);let previousState=null,previous=new Set(),pending=new Map(),lastFull=-1e9,lastCompact=-1e9;
const observe=cinema.observe.bind(cinema),draw=cinema.draw.bind(cinema),present=cinema.present.bind(cinema),finish=cinema.finish.bind(cinema),battleEvent=cinema.battleEvent.bind(cinema),musicFor=cinema.musicFor;
const motion=cinema.motionMedia=createMotionMedia();
cinema.finish=()=>{motion.dispose();return finish();};
cinema.musicFor=e=>{if(e.expansion){const track=manifest?.tracks.find(t=>t.id===e.musicId);return track?new URL('../music/rpg/'+track.audio,import.meta.url).href:null;}return musicFor?.(e);};
cinema.draw=t=>cinema.entry?.expansion?drawExpansion(cinema,t):draw(t);
cinema.present=(entry,world,options)=>{if(entry?.expansion){cinema.canvas.width=entry.compact?960:1920;cinema.canvas.height=entry.compact?540:1080;cinema.storyShotIndex=-1;cinema.root.classList.add('story-cinema');for(const shot of entry.shots)cinema.image(shot.art);}else{cinema.canvas.width=1280;cinema.canvas.height=720;cinema.root.classList.remove('story-cinema');}const shown=present(entry,world,options);if(shown)motion.start(entry,{reduced:cinema.reduced,compatibility:!!cinema.renderer?.compatibility});return shown;};
cinema.observe=(world,available)=>{const s=world.state;if(previousState!==s){const returned=previousState?.chronicle?.phase==='past'&&s.chronicle?.phase==='present'&&previousState.chronicle.originId===s.chronicle.originId;previousState=s;previous=new Set(entries.filter(e=>expansionEarned(e,s)).map(e=>e.id));pending.clear();if(returned){const ending=entries.find(e=>e.topic==='origin-return'&&e.originId===s.chronicle.originId);if(ending)pending.set(ending.id,ending);}}
const current=new Set(entries.filter(e=>expansionEarned(e,s)).map(e=>e.id));for(const e of entries)if(current.has(e.id)&&!previous.has(e.id)&&!seenCinematic(s,e.id))pending.set(e.id,e);previous=current;
if(available&&(!s.story||s.story.firstCore)){const region=entries.find(e=>e.topic==='region'&&e.regionScene===s.scene&&e.chapter<=s.chapter);if(region&&!seenCinematic(s,region.id)){if(!s.regionalLife)s.regionalLife={};s.regionalLife.visited??=[];if(!s.regionalLife.visited.includes(region.key))s.regionalLife.visited.push(region.key);pending.set(region.id,region);}}
observe(world,available);if(!cinema.enabled){pending.clear();return;}if(!available||cinema.busy||cinema.entry)return;const now=performance.now(),candidates=[...pending.values()].filter(e=>!seenCinematic(s,e.id)&&expansionEarned(e,s)).sort((a,b)=>a.priority-b.priority);pending=new Map(candidates.slice(0,6).map(e=>[e.id,e]));const next=candidates.find(e=>(explorationPresentation(e).compact?now-lastCompact>=12000:now-lastFull>=45000)&&(!e.regionScene||e.regionScene===s.scene));if(!next)return;
const image=cinema.image(next.shots[0].art);if(!image)return;pending.delete(next.id);const presentation=explorationPresentation(next);if(presentation.compact)lastCompact=now;else lastFull=now;cinema.present(presentation,world);};
cinema.battleEvent=(event,world)=>{if(event.type==='cast'&&event.tech?.doctrines?.length){world.state.cinemaDoctrines??=[];for(const school of event.tech.doctrines)if(school.root&&!world.state.cinemaDoctrines.includes(school.id))world.state.cinemaDoctrines.push(school.id);}if(event.type==='reaction'&&event.reaction){world.state.cinemaReactions??=[];if(!world.state.cinemaReactions.includes(event.reaction))world.state.cinemaReactions.push(event.reaction);}const keys=tacticKeys(event);if(keys.length){world.state.cinemaTactics??=[];for(const key of keys)if(!world.state.cinemaTactics.includes(key))world.state.cinemaTactics.push(key);}battleEvent(event,world);const now=performance.now();if(cinema.enabled&&!cinema.entry&&(keys.length||event.type==='reaction')&&now-lastCompact>=12000){const entry=entries.find(e=>((e.topic==='tactic'&&keys.includes(e.key))||(e.topic==='reaction'&&e.key===event.reaction))&&!seenCinematic(world.state,e.id));if(entry&&cinema.image(entry.shots[0].art)){lastCompact=now;cinema.present(entry,world);}}};return {entries};}
